import { parentPort, workerData } from 'node:worker_threads';
import { mkdir, readFile, writeFile, stat, rename, open } from 'node:fs/promises';
import { createReadStream } from 'node:fs';
import { createHash } from 'node:crypto';
import { availableParallelism } from 'node:os';
import { join, dirname } from 'node:path';

// Only short PCM16 WAV segments generated by the capture module are accepted.
// Decode/resample in this worker, never block Electron's main/UI thread.
export function decodePcmWav(bytes) {
  if (!(bytes instanceof ArrayBuffer) || bytes.byteLength < 44 || bytes.byteLength > 4 * 1024 * 1024) throw new Error('音频数据无效');
  const view = new DataView(bytes);
  const label = offset => String.fromCharCode(...new Uint8Array(bytes, offset, 4));
  if (label(0) !== 'RIFF' || label(8) !== 'WAVE' || view.getUint32(4, true) + 8 !== bytes.byteLength) throw new Error('音频容器无效');
  let format, data;
  for (let at = 12; at + 8 <= bytes.byteLength;) {
    const size = view.getUint32(at + 4, true), end = at + 8 + size;
    if (end > bytes.byteLength) throw new Error('音频长度无效');
    if (label(at) === 'fmt ' && size >= 16) format = { codec: view.getUint16(at + 8, true), channels: view.getUint16(at + 10, true), rate: view.getUint32(at + 12, true), align: view.getUint16(at + 20, true), bits: view.getUint16(at + 22, true) };
    if (label(at) === 'data') data = { at: at + 8, size };
    at = end + (size % 2);
  }
  if (!format || !data || format.codec !== 1 || format.bits !== 16 || ![1, 2].includes(format.channels)
    || format.align !== format.channels * 2 || format.rate < 8000 || format.rate > 192000
    || data.size === 0 || data.size % format.align !== 0) throw new Error('音频格式无效');
  const count = data.size / format.align;
  if (count / format.rate > 15) throw new Error('音频片段过长');
  const mono = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    let sample = 0;
    for (let channel = 0; channel < format.channels; channel++) sample += view.getInt16(data.at + i * format.align + channel * 2, true) / 32768;
    mono[i] = sample / format.channels;
  }
  if (format.rate === 16000) return mono;
  const ratio = format.rate / 16000, result = new Float32Array(Math.floor(count / ratio));
  if (ratio > 1) {
    // Area averaging suppresses high-frequency aliasing during downsampling.
    for (let i = 0; i < result.length; i++) {
      const start = i * ratio, end = Math.min(count, start + ratio);
      let sample = 0;
      for (let j = Math.floor(start); j < end; j++) sample += mono[j] * (Math.min(end, j + 1) - Math.max(start, j));
      result[i] = sample / (end - start);
    }
  } else {
    for (let i = 0; i < result.length; i++) {
      const at = i * ratio, left = Math.floor(at), fraction = at - left;
      result[i] = mono[left] * (1 - fraction) + mono[Math.min(left + 1, count - 1)] * fraction;
    }
  }
  return result;
}

if (parentPort) {
  const { directory, model } = workerData;
  const modelDirectory = join(directory, `whisper-base-${model.revision}`);
  const totalBytes = model.files.reduce((sum, item) => sum + item[1], 0);
  let transcriber, runtime, active = null, queued = null, preparing = false, lastProgress = 0;
  const send = message => parentPort.postMessage(message);
  function progress(status, loaded, force = false) {
    if (!force && Date.now() - lastProgress < 150) return;
    lastProgress = Date.now();
    send({ type: 'progress', status, progress: Math.min(100, loaded / totalBytes * 100) });
  }
  async function validFile(path, size, expectedHash) {
    try {
      if ((await stat(path)).size !== size) return false;
      if (!expectedHash) return true;
      const hash = createHash('sha256');
      for await (const chunk of createReadStream(path)) hash.update(chunk);
      return hash.digest('hex') === expectedHash;
    } catch { return false; }
  }
  async function obtainFiles(allowDownload) {
    let loaded = 0;
    for (const [name, size, expectedHash] of model.files) {
      const path = join(modelDirectory, name);
      if (await validFile(path, size, expectedHash)) { loaded += size; continue; }
      if (!allowDownload) throw Object.assign(new Error(), { code: 'cache' });
      progress('downloading', loaded, true);
      await mkdir(dirname(path), { recursive: true });
      const response = await fetch(`https://huggingface.co/${model.id}/resolve/${model.revision}/${name}`, { signal: AbortSignal.timeout(5 * 60_000) });
      if (!response.ok || !response.body) throw Object.assign(new Error(), { code: 'download' });
      const file = await open(`${path}.partial`, 'w');
      const hash = createHash('sha256');
      let received = 0;
      try {
        for await (const chunk of response.body) {
          received += chunk.byteLength;
          if (received > size) throw new Error();
          hash.update(chunk);
          await file.writeFile(chunk);
          progress('downloading', loaded + received);
        }
      } finally { await file.close(); }
      if (received !== size || (expectedHash && hash.digest('hex') !== expectedHash)) throw Object.assign(new Error(), { code: 'download' });
      await rename(`${path}.partial`, path);
      loaded += size;
      progress('downloading', loaded, true);
    }
  }
  async function prepare(message) {
    if (preparing) { send({ type: 'result', id: message.id, ok: false, code: 'busy' }); return; }
    preparing = true;
    let stage = 'download';
    try {
      await obtainFiles(message.allowDownload === true);
      stage = 'load';
      progress('loading', totalBytes, true);
      runtime ??= await import('@huggingface/transformers');
      runtime.env.allowRemoteModels = false;
      runtime.env.allowLocalModels = true;
      runtime.env.useFSCache = false;
      transcriber ??= await runtime.pipeline('automatic-speech-recognition', modelDirectory, {
        dtype: model.dtype, device: 'cpu', local_files_only: true,
        session_options: { intraOpNumThreads: Math.max(1, Math.min(4, availableParallelism() - 1)), interOpNumThreads: 1 },
      });
      await writeFile(join(directory, 'ready.json'), JSON.stringify({ id: model.id, revision: model.revision, dtype: model.dtype }), 'utf8');
      send({ type: 'result', id: message.id, ok: true });
    } catch (error) { send({ type: 'result', id: message.id, ok: false, code: error.code === 'cache' ? 'cache' : stage }); }
    finally { preparing = false; }
  }
  async function transcribe(message) {
    if (!transcriber) { send({ type: 'result', id: message.id, ok: false, code: 'load' }); return; }
    if (active) {
      if (queued) send({ type: 'result', id: message.id, ok: false, code: 'busy' });
      else queued = message;
      return;
    }
    const job = { id: message.id, cancelled: false, stopping: new runtime.InterruptableStoppingCriteria() };
    active = job;
    let stage = 'audio';
    try {
      const audio = decodePcmWav(message.bytes);
      let energy = 0;for (const sample of audio) energy += sample * sample;
      stage = 'inference';
      // Silence has no transcript; avoids Whisper's known silence hallucinations.
      const output = audio.length && Math.sqrt(energy / audio.length) >= 0.001
        ? await transcriber(audio, { language: 'chinese', task: 'transcribe', max_new_tokens: 128, stopping_criteria: [job.stopping] })
        : { text: '' };
      if (!job.cancelled) send({ type: 'result', id: message.id, ok: true, text: String(output.text || '').trim() });
    } catch { if (!job.cancelled) send({ type: 'result', id: message.id, ok: false, code: stage }); }
    finally {
      active = null;
      const next = queued;queued = null;
      if (next) void transcribe(next);
    }
  }
  parentPort.on('message', message => {
    if (message.type === 'prepare') void prepare(message);
    if (message.type === 'transcribe') void transcribe(message);
    if (message.type === 'cancel') {
      if (active?.id === message.id) { active.cancelled = true;active.stopping.interrupt(); }
      if (queued?.id === message.id) queued = null;
    }
  });
}
